import { DndContext } from "@dnd-kit/core";
import Board from "./components/Board";
import { useBoard } from "./hooks/useBoard";
import { arrayMove } from "@dnd-kit/sortable";

function App() {
  const { board, setBoard } = useBoard();

  const handleDragEnd = (event: any) => {
  const { active, over } = event;
    console.log("Active:", active, "Over:", over, "Event:", event);
  if (!over || active.id === over.id) return;

  setBoard((prev) => {
  // Find column
  const column = Object.values(prev.columns).find((col) =>{
    console.log("---",col.cardIds, active.id);
    return col.cardIds.includes(active.id)
  });

  if (!column) return prev;

  const oldIndex = column.cardIds.indexOf(active.id);
  const newIndex = column.cardIds.indexOf(over.id);

  if (oldIndex === -1 || newIndex === -1) return prev;

  const newCardIds = arrayMove(column.cardIds, oldIndex, newIndex,);
  console.log("New Card IDs:",newCardIds,column.id,  {
      ...prev.columns,
      [column.id]: {
        ...column,
        cardIds: newCardIds,
      },
    },);
  return {
    ...prev,
    columns: {
      ...prev.columns,
      [column.id]: {
        ...column,
        cardIds: newCardIds,
      },
    },
  };
});
};
  return (
    <div style={{ flex: 1,height: window.innerHeight, padding: 20, backgroundColor: "rgb(16,22,62)" }}>
      <DndContext onDragEnd={handleDragEnd}>
      <Board board={board} />
      </DndContext>
    </div>
  );
}

export default App;
